using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Polarity.Config;using Polarity.Entities;using Codely.Newtonsoft.Json;using Object=UnityEngine.Object;
var def=AssetDatabase.LoadAssetAtPath<LevelDefinition>("Assets/Polarity/Configs/Levels/04-ChooseSource.asset");var path=AssetDatabase.GetAssetPath(def.RoomPrefab);var root=PrefabUtility.LoadPrefabContents(path);try{var room=root.GetComponent<LevelRoom>();room.Player.transform.localPosition=new Vector3(3.5f,-2,0);var bodies=room.CopyBodies();if(bodies.Length!=6)throw new Exception("Expected 4 enemies 2 crates: "+bodies.Length);var ps=new[]{new Vector3(-3.2f,-.4f,0),new Vector3(-4.4f,.2f,0),new Vector3(-1.5f,1.8f,0),new Vector3(-2.5f,3.2f,0),new Vector3(.5f,.1f,0),new Vector3(2.3f,2,0)};for(int i=0;i<6;i++){bodies[i].transform.localPosition=ps[i];var so=new SerializedObject(bodies[i]);so.FindProperty("initialPolarity").enumValueIndex=0;so.ApplyModifiedPropertiesWithoutUndo();if(i<4){var hs=new SerializedObject(bodies[i].GetComponent<Health>());hs.FindProperty("maxHealth").intValue=2;hs.ApplyModifiedPropertiesWithoutUndo();var es=new SerializedObject(bodies[i].GetComponent<EnemyMotor>());es.FindProperty("chaseSpeed").floatValue=2.2f;es.ApplyModifiedPropertiesWithoutUndo();}}
var hazards=root.GetComponentsInChildren<SpikeHazard>(true);if(hazards.Length!=2)throw new Exception("Expected 2 hazards "+hazards.Length);for(int i=0;i<2;i++){hazards[i].name=i==0?"Spikes_Left":"Spikes_Upper";hazards[i].transform.localPosition=i==0?new Vector3(-5.5f,0,0):new Vector3(-2.5f,4.3f,0);var size=i==0?new Vector2(.8f,2.5f):new Vector2(3.2f,.7f);hazards[i].GetComponent<BoxCollider2D>().size=size;foreach(var sr in hazards[i].GetComponentsInChildren<SpriteRenderer>())sr.transform.localScale=new Vector3(size.x,size.y,1);}
if(room.CopyTurrets().Length!=0)throw new Exception("Unexpected turret");PrefabUtility.SaveAsPrefabAsset(root,path);var ds=new SerializedObject(def);ds.FindProperty("title").stringValue="选择起点";ds.FindProperty("markBudget").intValue=3;ds.FindProperty("teachingHint").stringValue="改色只改变当前对象，已有极性不会被接触覆盖。先标谁、在哪里接触，会改变后续局面。借箱子与局部尖刺清除四敌；空格慢速，R重试。";ds.ApplyModifiedPropertiesWithoutUndo();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());return JsonConvert.SerializeObject(new{path,bodies=bodies.Select((b,i)=>new{id=i+1,name=b.name,xy=new[]{b.transform.localPosition.x,b.transform.localPosition.y}}).ToArray(),hazards=hazards.Select(h=>new{name=h.name,xy=new[]{h.transform.localPosition.x,h.transform.localPosition.y},size=new[]{h.GetComponent<BoxCollider2D>().size.x,h.GetComponent<BoxCollider2D>().size.y}}).ToArray(),valid=room.HasValidBindings()});}finally{PrefabUtility.UnloadPrefabContents(root);}

