using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Polarity.Config;using Polarity.Controllers;using Polarity.Entities;using Polarity.Model;using Polarity.Simulation;using Polarity.Views;using Polarity.Debugging;using Codely.Newtonsoft.Json;using Object=UnityEngine.Object;
var flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;EditorApplication.isPaused=true;
async Task<SimulationWorld> Load(int index=3){var old=Object.FindObjectOfType<SimulationWorld>();typeof(LevelController).GetField("<CurrentLevelIndex>k__BackingField",flags).SetValue(old.Level,index);var done=new TaskCompletionSource<SimulationWorld>();UnityEngine.Events.UnityAction<Scene,LoadSceneMode> cb=null;cb=(s,m)=>{SceneManager.sceneLoaded-=cb;EditorApplication.isPaused=true;done.SetResult(Object.FindObjectOfType<SimulationWorld>());};SceneManager.sceneLoaded+=cb;EditorApplication.isPaused=false;if(!old.Level.RequestRestart())throw new Exception("restart rejected");return await done.Task;}
var stepMethod=typeof(SimulationWorld).GetMethod("FixedUpdate",flags);void Step(SimulationWorld w)=>stepMethod.Invoke(w,null);float[] V(Vector2 p)=>new[]{p.x,p.y};void Walk(SimulationWorld w,Vector2 to){var d=to-w.Player.Rigidbody.position;w.Player.SampleMoveInput(d.y>.12f,d.x<-.12f,d.y<-.12f,d.x>.12f);}
void Configure(SimulationWorld w){}
async Task<object> Case(string name,int[] markAt,int[] ids,int[] poles,Vector2[] goals,int[] switchAt,int limit=2000){var w=await Load();Configure(w);var actors=w.Bodies.ToArray();var initial=actors.Select(b=>new{id=b.BodyId,xy=V(b.Rigidbody.position),polarity=b.CurrentPolarity.ToString(),hp=b.GetComponent<Health>()!=null?b.GetComponent<Health>().CurrentHealth:0}).ToArray();var marks=new List<object>();var spread=new List<object>();var hits=new List<object>();var traces=new List<object>();var contacts=new List<object>();string previous="";w.MarkResolved+=r=>marks.Add(new{step=w.CompletedStepCount+1,time=w.SimulationTime+.02,r.Request.TargetId,pole=r.Request.Polarity.ToString(),outcome=r.Outcome.ToString(),budget=w.State.RemainingMarks});w.PropagationCommitted+=r=>spread.Add(new{r.Step,time=w.SimulationTime,r.SourceId,r.TargetId,pole=r.Polarity.ToString(),r.NormalImpulse,source=V(r.SourcePosition),target=V(r.TargetPosition),budget=w.State.RemainingMarks});w.DamageCommitted+=r=>hits.Add(new{r.Step,time=w.SimulationTime,r.TargetId,r.SourceId,kind=r.Kind.ToString(),r.NormalSpeed,r.RemainingHealth,xy=V(r.Position)});
for(int i=0;i<limit&&w.State.Phase==LevelPhase.Running;i++){for(int k=0;k<markAt.Length;k++)if(i==markAt[k])w.SubmitMark(ids[k],(Polarity.Model.Polarity)poles[k]);int dest=-1;for(int k=0;k<switchAt.Length;k++)if(i>=switchAt[k])dest=k;if(dest>=0)Walk(w,goals[dest]);else w.Player.SampleMoveInput(false,false,false,false);Step(w);string pairs=string.Join(",",w.LastContactPairs.Select(p=>p.AId+"-"+p.BId));var states=actors.Where(b=>b!=null).Select(b=>{Vector2 force;w.TryGetLastMagneticForce(b,out force);return new{id=b.BodyId,xy=V(b.Rigidbody.position),v=V(b.Rigidbody.velocity),pole=b.CurrentPolarity.ToString(),force=V(force),hp=b.GetComponent<Health>()!=null?b.GetComponent<Health>().CurrentHealth:0};}).ToArray();if(pairs!=previous){previous=pairs;contacts.Add(new{step=w.CompletedStepCount,pairs,states});}if(i%25==0||w.LastPropagationResults.Count>0||w.LastDamageResults.Count>0||markAt.Contains(i))traces.Add(new{step=w.CompletedStepCount,p=V(w.Player.Rigidbody.position),states});}
return new{name,initial,markAt,ids,poles,goals=goals.Select(V).ToArray(),switchAt,phase=w.State.Phase.ToString(),steps=w.CompletedStepCount,time=w.SimulationTime,hp=w.PlayerHealth.CurrentHealth,enemies=w.State.ActiveEnemyCount,budget=w.State.RemainingMarks,failed=w.FailedStepCount,gm=w.GetComponent<GMManager>().Invincible||w.GetComponent<GMManager>().UnlimitedMarks,marks,spread,hits,traces,contacts};}
async Task<string> Run(){var all=new List<object>();all.Add(await Case("A",new[]{20,40,160},new[]{1,5,3},new[]{1,2,2},new[]{new Vector2(1,2.5f),new Vector2(-3,2.5f),new Vector2(-7,3)},new[]{40,130,300}));all.Add(await Case("B",new[]{20,40,160},new[]{3,6,6},new[]{1,2,1},new[]{new Vector2(1,3),new Vector2(-4,3),new Vector2(-7,3)},new[]{0,120,300}));all.Add(await Case("none",new int[0],new int[0],new int[0],new[]{new Vector2(-7,3)},new[]{0})); System.IO.File.WriteAllText("D:/Code/Polarity/docs/verification/步骤15-种子探索.json",JsonConvert.SerializeObject(all));return JsonConvert.SerializeObject(all.Select(o=>new{name=o.GetType().GetProperty("name").GetValue(o),phase=o.GetType().GetProperty("phase").GetValue(o),enemies=o.GetType().GetProperty("enemies").GetValue(o),hp=o.GetType().GetProperty("hp").GetValue(o)}));}return Run();

