ird=true;}if(routeA){if(n>=450)Walk(w,new Vector2(-8,2));else if(n>=330)Walk(w,new Vector2(1,3));else if(n>=180)Walk(w,new Vector2(7,3));else Walk(w,new Vector2(5,-2));}else{if(n>=470)Walk(w,new Vector2(-8,3));else if(n>=340)Walk(w,new Vector2(1,5.3f));else if(n>=180)Walk(w,new Vector2(7,4));else Walk(w,new Vector2(5,-2));}if(n!=previous&&(n%25==0||w.LastPropagationResults.Count>0||w.LastDamageResults.Count>0)){previous=n;traces.Add(new{step=n,p=V(w.Player.Rigidbody.position),states=actors.Where(b=>b!=null).Select(b=>new{id=b.BodyId,xy=V(b.Rigidbody.position),v=V(b.Rigidbody.velocity),pole=b.CurrentPolarity.ToString(),hp=b.GetComponent<Health>()!=null?b.GetComponent<Health>().CurrentHealth:0}).ToArray()});}if(!slow&&routeA&&!captured&&spread.Any(r=>((long)r.GetType().GetProperty("Step").GetValue(r))>=190)){SaveFrame("局部改色后新传播");captured=true;}}yield return new WaitForEndOfFrame();if(!slow)SaveFrame(name+"-结算");var hud=Object.FindObjectOfType<HUDView>();EditorApplication.isPaused=true;done.SetResult(new{name,routeA,slow,mode="automatic engine FixedUpdate; input API only",realSeconds=Time.realtimeSinceStartup-started,phase=w.State.Phase.ToString(),time=w.SimulationTime,steps=w.CompletedStepCount,fixedUpdates=w.FixedUpdateCount,attempts=w.SimulationAttemptCount,failed=w.FailedStepCount,hp=w.PlayerHealth.CurrentHealth,budget=w.State.RemainingMarks,enemies=w.State.ActiveEnemyCount,gm=w.GetComponent<GMManager>().Invincible||w.GetComponent<GMManager>().UnlimitedMarks,marks,spread,hits,traces,hudMarks=hud.MarkNotificationCount,hudSpread=hud.PropagationNotificationCount,hudModal=hud.ModalVisible});}w.Player.StartCoroutine(Frames());return await done.Task;}
